// What a house is billed for this month (rent and utilities separately),
// worked out from its billing holds, and how to change it without touching
// past months.
//
// Holds that already covered past months are ended at last month rather than
// canceled: recurring utility charges are generated by walking forward from
// the house's last real bill and skipping held months, so canceling a hold
// that started months ago bills every one of those months retroactively.

import { OPEN_ENDED_BILLING_MONTH } from "../validation/schemas.js";

export type BillingHoldScope = "rent" | "utilities" | "all";
export type BillingUtilityType = "water" | "electricity";

export interface HouseBillingHold {
  id: string;
  scope: BillingHoldScope;
  utilityType?: BillingUtilityType;
  startMonth: string;
  endMonth: string;
  reason?: string;
}

export interface ChargeBillingStatus {
  billed: boolean;
  // Utilities only: set when just one utility is excluded.
  utilityType?: BillingUtilityType;
  reason?: string;
  // Last month that isn't billed; undefined = until resumed.
  untilMonth?: string;
}

export interface HouseBillingStatus {
  rent: ChargeBillingStatus;
  utilities: ChargeBillingStatus;
}

export interface DesiredChargeBilling {
  billed: boolean;
  utilityType?: BillingUtilityType;
  reason?: string;
  untilMonth?: string;
}

export interface HouseBillingPlan {
  end: Array<{ id: string; endMonth: string }>;
  cancel: string[];
  create: Array<Omit<HouseBillingHold, "id">>;
}

export function shiftBillingMonth(month: string, delta: number): string {
  const [year, monthPart] = month.split("-").map(Number);
  const index = year * 12 + (monthPart - 1) + delta;
  return `${Math.floor(index / 12)}-${String((index % 12) + 1).padStart(2, "0")}`;
}

function covers(hold: HouseBillingHold, month: string) {
  return hold.startMonth <= month && month <= hold.endMonth;
}

function statusFrom(holds: HouseBillingHold[]): ChargeBillingStatus {
  if (holds.length === 0) return { billed: true };
  const lastMonth = holds.map((hold) => hold.endMonth).sort().at(-1) as string;
  return {
    billed: false,
    reason: holds.find((hold) => hold.reason?.trim())?.reason?.trim(),
    untilMonth: lastMonth >= OPEN_ENDED_BILLING_MONTH ? undefined : lastMonth
  };
}

export function houseBillingStatus(holds: HouseBillingHold[], month: string): HouseBillingStatus {
  const current = holds.filter((hold) => covers(hold, month));
  const rent = statusFrom(current.filter((hold) => hold.scope === "rent" || hold.scope === "all"));
  const utilityHolds = current.filter((hold) => hold.scope === "utilities" || hold.scope === "all");
  const utilities = statusFrom(utilityHolds);
  // Only a partial exclusion when every covering utility hold names the same one.
  if (!utilities.billed && utilityHolds.every((hold) => hold.scope === "utilities" && hold.utilityType)) {
    const types = new Set(utilityHolds.map((hold) => hold.utilityType));
    if (types.size === 1) utilities.utilityType = utilityHolds[0].utilityType;
  }
  return { rent, utilities };
}

// Replaces whatever covers `month` with holds matching `desired`, from
// `month` on. Holds that only start later (a pause already planned for next
// month) are left alone.
export function planHouseBillingChange(
  holds: HouseBillingHold[],
  month: string,
  desired: { rent: DesiredChargeBilling; utilities: DesiredChargeBilling }
): HouseBillingPlan {
  const plan: HouseBillingPlan = { end: [], cancel: [], create: [] };
  for (const hold of holds.filter((item) => covers(item, month))) {
    if (hold.startMonth < month) plan.end.push({ id: hold.id, endMonth: shiftBillingMonth(month, -1) });
    else plan.cancel.push(hold.id);
  }

  const endMonth = (charge: DesiredChargeBilling) => charge.untilMonth ?? OPEN_ENDED_BILLING_MONTH;
  const rentOff = !desired.rent.billed;
  const utilitiesOff = !desired.utilities.billed;
  const same =
    rentOff && utilitiesOff && !desired.utilities.utilityType &&
    endMonth(desired.rent) === endMonth(desired.utilities) &&
    (desired.rent.reason ?? "").trim() === (desired.utilities.reason ?? "").trim();

  if (same) {
    plan.create.push({ scope: "all", startMonth: month, endMonth: endMonth(desired.rent), reason: desired.rent.reason?.trim() });
    return plan;
  }
  if (rentOff) {
    plan.create.push({ scope: "rent", startMonth: month, endMonth: endMonth(desired.rent), reason: desired.rent.reason?.trim() });
  }
  if (utilitiesOff) {
    plan.create.push({
      scope: "utilities",
      utilityType: desired.utilities.utilityType,
      startMonth: month,
      endMonth: endMonth(desired.utilities),
      reason: desired.utilities.reason?.trim()
    });
  }
  return plan;
}
